fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper function to compute S(k) as defined:
    // S(k) = k/2 if k is even
    // S(k) = -(k+1)/2 if k is odd
    fn prefix_sum(k: i8) -> i8 {
        if k == 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| prefix_sum(r) - prefix_sum(l - 1))
        .collect()
}